import{_ as p,a0 as o,w as l,s as d,I as a,x as e,a1 as i,A as t,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const B=JSON.parse('{"title":"在 OBS 中將攝像頭鎖定到特定的 USB 端口 | LCTT x X-CMD","titleTemplate":false,"description":"在 OBS 中將攝像頭鎖定到特定的 USB 端口 | LCTT (202305) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 OBS 中將攝像頭鎖定到特定的 USB 端口 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 OBS 中將攝像頭鎖定到特定的 USB 端口 | LCTT (202305) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202305/20220107 Lock your camera to a specific USB port in OBS","title":"在 OBS 中將攝像頭鎖定到特定的 USB 端口","tag":"202305","desc":""},"relativePath":"202305/20220107 Lock your camera to a specific USB port in OBS.md","filePath":"[post].md"}'),u={name:"202305/20220107 Lock your camera to a specific USB port in OBS.md"};function c(h,s,b,g,v,m){const n=o("Link");return l(),d("div",null,[s[18]||(s[18]=a("h1",{id:"在-obs-中將攝像頭鎖定到特定的-usb-端口",tabindex:"-1"},[e("在 OBS 中將攝像頭鎖定到特定的 USB 端口 "),a("a",{class:"header-anchor",href:"#在-obs-中將攝像頭鎖定到特定的-usb-端口","aria-label":"Permalink to “在 OBS 中將攝像頭鎖定到特定的 USB 端口”"},"​")],-1)),s[19]||(s[19]=a("blockquote",null,[a("p",null,"為了使複雜的攝像頭設置標準化，你可以對 Linux 文件系統中攝像頭的位置分配施加一些特殊規則。")],-1)),s[20]||(s[20]=a("p",null,[a("img",{src:"https://img.linux.net.cn/data/attachment/album/202305/06/233102xqfzerq9mek1e9mt.png",alt:""})],-1)),a("p",null,[s[1]||(s[1]=e("如果在 Linux 上用多個攝像頭 ",-1)),i(n,{href:"https://opensource.com/life/15/12/real-time-linux-video-editing-with-obs-studio"},{default:t(()=>[...s[0]||(s[0]=[e("使用 OBS 進行直播",-1)])]),_:1}),s[2]||(s[2]=e("，你可能會注意到攝像頭會在開機時按照它們被檢測到的順序加載。通常情況下你不需要特別在意，但如果你有一個固定的直播設置和複雜的 OBS 模板，你需要知道現實世界中哪個攝像頭將會顯示在虛擬世界的哪個屏幕上。換句話説，你不希望今天將一個設備分配為“攝像頭 A”，而明天它卻成為“攝像頭 B”。",-1))]),s[21]||(s[21]=r(`<p>為了使複雜的攝像頭設置標準化，你可以對 Linux 文件系統中攝像頭的位置分配施加一些特殊規則。</p><h3 id="udev-子系統" tabindex="-1">udev 子系統 <a class="header-anchor" href="#udev-子系統" aria-label="Permalink to “udev 子系統”">​</a></h3><p>在 Linux 上處理硬件外設的系統稱為 udev。它檢測和管理你接入計算機的所有設備。你可能沒有意識到它的存在，因為它不會吸引太多注意力。儘管當你插入 USB 閃存驅動器以在桌面上打開它或連接打印機時，你肯定與它交互過。</p><h3 id="硬件檢測" tabindex="-1">硬件檢測 <a class="header-anchor" href="#硬件檢測" aria-label="Permalink to “硬件檢測”">​</a></h3><p>假設你有兩個 USB 攝像頭：一個在電腦左側，另一個在右側。左側攝像頭拍攝近景，右側攝像頭拍攝遠景，並且在直播過程中你需要切換兩個攝像頭。在 OBS 中，你將每個攝像頭添加到 <ruby>源<rt>Sources</rt></ruby> 面板中，並直觀地將它們命名為 “camLEFT” 和 “camRIGHT”。</p><p>設想一種最壞的場景，你有兩個 <em>相同的</em> 攝像頭：它們是同一品牌、同一型號。這是最壞的情況，因為當兩個硬件設備完全相同時，它們幾乎不可能有任何獨特的 ID，以便你的電腦能夠將它們區分開來。</p><p>不過，這個難題有解決辦法，只需要一些簡單的終端命令進行一些調查。</p><h4 id="_1、獲取廠商和產品-id" tabindex="-1">1、獲取廠商和產品 ID <a class="header-anchor" href="#_1、獲取廠商和產品-id" aria-label="Permalink to “1、獲取廠商和產品 ID”">​</a></h4><p>首先，將一個攝像頭插入你想要它分配到的 USB 端口。然後輸入以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ lsusb</span></span>
<span class="line"><span>Bus 006 Device 002: ID 0951:1666 Kingston Technology DataTraveler G4</span></span>
<span class="line"><span>Bus 005 Device 003: ID 03f0:3817 Hewlett-Packard LaserJet P2015 series</span></span>
<span class="line"><span>Bus 003 Device 006: ID 045e:0779 Microsoft Corp. LifeCam HD-3000</span></span>
<span class="line"><span>Bus 003 Device 002: ID 8087:0025 Intel Corp. </span></span>
<span class="line"><span>Bus 002 Device 001: ID 1d6b:0003 Linux Foundation 3.0 root hub</span></span>
<span class="line"><span>Bus 001 Device 003: ID 046d:c216 Logitech, Inc. Dual Action Gamepad</span></span>
<span class="line"><span>Bus 001 Device 002: ID 048d:5702 Integrated Technology Express, Inc. </span></span>
<span class="line"><span>Bus 001 Device 001: ID 1d6b:0002 Linux Foundation 2.0 root hub</span></span>
<span class="line"><span>[...]</span></span></code></pre></div><p>你通常可以專門搜索字符串 <code>cam</code> 以縮小結果範圍，因為大多數（但不是所有）攝像頭都會報告為 “camera”。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ lsusb | grep -i cam</span></span>
<span class="line"><span>Bus 003 Device 006: ID 045e:0779 Microsoft Corp. LifeCam HD-3000</span></span></code></pre></div><p>這裏有很多信息。ID 被列為 <code>045e:0779</code>。第一個數字是供應商 ID，第二個數字是產品 ID。把它們寫下來，因為稍後你會需要它們。</p><h4 id="_2、獲取-usb-標識符" tabindex="-1">2、獲取 USB 標識符 <a class="header-anchor" href="#_2、獲取-usb-標識符" aria-label="Permalink to “2、獲取 USB 標識符”">​</a></h4><p>你還獲取了攝像頭的設備路徑：總線 3，設備 6。在 Linux 中有一句話：“一切皆文件”，實際上，USB 設備被描述為以 <code>/dev/bus/usb/</code> 開始，以總線（本例中為 003）和設備（本例中為 006）結尾的文件路徑。查看 <code>lsusb</code> 輸出中的總線和設備號。它們告訴你該攝像頭位於 <code>/dev/bus/usb/003/006</code>。</p><p>你可以使用 <code>udevadm</code> 命令獲取此 USB 設備的內核代號：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo udevadm info --attribute-walk /dev/bus/usb/003/006 | grep &quot;KERNEL=&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>   KERNEL==&quot;3-6.2.1&quot;</span></span></code></pre></div><p>這個例子中的內核 USB 標識符是 <code>3-6.2.1</code>。把你係統中的標識符記下來，因為之後也會用到它。</p><h4 id="_3、為每個攝像頭重複該過程" tabindex="-1">3、為每個攝像頭重複該過程 <a class="header-anchor" href="#_3、為每個攝像頭重複該過程" aria-label="Permalink to “3、為每個攝像頭重複該過程”">​</a></h4><p>將另一個攝像頭（如果你有多個攝像頭，則為每個攝像頭）連接到要分配給它的 USB 端口。這與你用於另一個攝像頭的 USB 端口是不同的！</p><p>重複該過程，獲取供應商和產品 ID（如果攝像頭是相同的品牌和型號，則應與第一個攝像頭相同）以及內核 USB 標識符。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ lsusb | grep -i cam</span></span>
<span class="line"><span>Bus 001 Device 004: ID 045e:0779 Microsoft Corp. LifeCam HD-3000</span></span>
<span class="line"><span>$ sudo udevadm info --attribute-walk dev/bus/usb/001/004 | grep &quot;KERNEL=&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>   KERNEL==&quot;1-6&quot;</span></span></code></pre></div><p>在這個例子中，我已經確定我的攝像頭連接到了 1-6 和 3-6.2.1（第一個是我的機器上的 USB 端口，另一個是插在我的機器上的顯示器插口的集線器，這就是為什麼一個比另一個更復雜的原因）。</p><h3 id="編寫一個-udev-規則" tabindex="-1">編寫一個 udev 規則 <a class="header-anchor" href="#編寫一個-udev-規則" aria-label="Permalink to “編寫一個 udev 規則”">​</a></h3><p>你已經有了所需的一切，因此現在可以編寫一個規則，告訴 udev 在特定的 USB 端口找到一個攝像頭時給它一個一致的標識符。</p><p>創建並打開一個名為 <code>/etc/udev/rules.d/50-camera.conf</code> 的文件，並輸入這兩個規則，使用適合你自己系統的廠商和產品 ID 和內核標識符：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>SUBSYSTEM==&quot;usb&quot;, KERNEL==&quot;1-6&quot;, ATTR{idVendor}==&quot;045e&quot;, ATTR{idProduct}==&quot;0779&quot;, SYMLINK+=&quot;video100&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>SUBSYSTEM==&quot;usb&quot;, KERNEL==&quot;3-6.2.1&quot;, ATTR{idVendor}==&quot;045e&quot;, ATTR{idProduct}==&quot;0779&quot;, SYMLINK+=&quot;video101&quot;</span></span></code></pre></div><p>這些規則告訴 udev，當在特定的 USB 位置找到與特定供應商和產品 ID 匹配的設備時，創建一個名為 <code>video100</code> 和 <code>video101</code> 的符號鏈接（有時也稱為“別名”）。符號鏈接大多是任意的。我使用較大的數字，這樣它們就容易被發現，並且數字不能與現有設備衝突。如果實際上有超過 101 個攝像頭連接到計算機上，請使用 <code>video200</code> 和 <code>video201</code> 以確保安全（記得聯繫我！我很想了解 <em>該</em> 項目的情況）。</p><h3 id="重啓" tabindex="-1">重啓 <a class="header-anchor" href="#重啓" aria-label="Permalink to “重啓”">​</a></h3><p>重新啓動計算機。你現在可以讓攝像頭保持連接在計算機上，但實際上這並不重要。一旦 udev 加載了規則，它就會遵循這些規則，無論設備是否在啓動期間附加或稍後插入。</p><p>許多人説 Linux 從不需要重啓，但是 udev 在引導期間加載其規則，而且此外，你想保證你的 udev 規則在重新啓動時也起作用。</p><p>計算機重新啓動後，請查看攝像頭註冊的 <code>/dev/video</code> 目錄：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -1 /dev/video*</span></span>
<span class="line"><span>/dev/video0</span></span>
<span class="line"><span>/dev/video1</span></span>
<span class="line"><span>/dev/video100</span></span>
<span class="line"><span>/dev/video101</span></span>
<span class="line"><span>/dev/video2</span></span>
<span class="line"><span>/dev/video3</span></span></code></pre></div><p>正如你所看到的，在 <code>video100</code> 和 <code>video101</code> 有條目。今天，這些是指向 <code>/dev/video2</code> 和 <code>/dev/video3</code> 的符號鏈接，但明天它們可能是指向 <code>/dev/video1</code> 和 <code>/dev/video2</code> 或任何其他基於 Linux 檢測和分配文件的組合。</p><p><img src="https://opensource.com/sites/default/files/uploads/obs-udev.jpg" alt="兩個攝像頭角度" title="Two camera angles"></p><p>你可以在 OBS 中使用這些符號鏈接，這樣 camLEFT 始終是 camLEFT，camRIGHT 始終是 camRIGHT。</p><p><em>（題圖：MJ/9bb70b6d-9f49-493a-8daf-5546d207781f）</em></p><hr>`,38)),a("p",null,[s[4]||(s[4]=e("via: ",-1)),i(n,{href:"https://opensource.com/article/22/1/cameras-usb-ports-obs"},{default:t(()=>[...s[3]||(s[3]=[e("https://opensource.com/article/22/1/cameras-usb-ports-obs",-1)])]),_:1})]),a("p",null,[s[9]||(s[9]=e("作者：",-1)),i(n,{href:"https://opensource.com/users/seth"},{default:t(()=>[...s[5]||(s[5]=[e("Seth Kenlon",-1)])]),_:1}),s[10]||(s[10]=e(" 選題：",-1)),i(n,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[6]||(s[6]=[e("lujun9972",-1)])]),_:1}),s[11]||(s[11]=e(" 譯者：",-1)),i(n,{href:"https://github.com/hanszhao80"},{default:t(()=>[...s[7]||(s[7]=[e("hanszhao80",-1)])]),_:1}),s[12]||(s[12]=e(" 校對：",-1)),i(n,{href:"https://github.com/wxy"},{default:t(()=>[...s[8]||(s[8]=[e("wxy",-1)])]),_:1})]),a("p",null,[s[15]||(s[15]=e("本文由 ",-1)),i(n,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[13]||(s[13]=[e("LCTT",-1)])]),_:1}),s[16]||(s[16]=e(" 原創編譯，",-1)),i(n,{href:"https://linux.cn/"},{default:t(()=>[...s[14]||(s[14]=[e("Linux中國",-1)])]),_:1}),s[17]||(s[17]=e(" 榮譽推出",-1))])])}const S=p(u,[["render",c]]);export{B as __pageData,S as default};
